<?php require __DIR__.'/bootstrap.php';require __DIR__.'/bootstrap_auth.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('dashboard.php');check_csrf();$id=(int)$_POST['tour_id'];$q=db()->prepare("SELECT id FROM tours WHERE id=?");$q->execute([$id]);if($q->fetch()){$_SESSION['tour_id']=$id;audit('SWITCH_TOUR','tour',$id);}redirect($_SERVER['HTTP_REFERER']??'dashboard.php');